import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Keynote- IBM’s Commitment, Investment, and Direction for Ceph in 2026 - Gilad Sade & Neha Ojha","description":"","frontmatter":{"title":"Keynote- IBM’s Commitment, Investment, and Direction for Ceph in 2026 - Gilad Sade & Neha Ojha","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","IBM","Open Source","Distributed Storage","Cloud Computing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_IBM_s_Commitment_Investment_and_Direction_for_Ceph_in_2026_-_Gilad_Sade_Neha_Ojha.md","filePath":"posts/2025/Keynote_-_IBM_s_Commitment_Investment_and_Direction_for_Ceph_in_2026_-_Gilad_Sade_Neha_Ojha.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Keynote_-_IBM_s_Commitment_Investment_and_Direction_for_Ceph_in_2026_-_Gilad_Sade_Neha_Ojha.md"};function s(i,e,_,l,h,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h3 id="ibm-2026年ceph战略规划会议纪要" tabindex="-1">IBM 2026年Ceph战略规划会议纪要 <a class="header-anchor" href="#ibm-2026年ceph战略规划会议纪要" aria-label="Permalink to &quot;IBM 2026年Ceph战略规划会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>：2026年Ceph相关会议<br><strong>主讲人</strong>：Neha Ojha（IBM Ceph项目总监） &amp; Gilad Sade（IBM存储技术专家）</p><h4 id="_1-ibm对ceph的承诺与投资" tabindex="-1"><strong>1. IBM对Ceph的承诺与投资</strong> <a class="header-anchor" href="#_1-ibm对ceph的承诺与投资" aria-label="Permalink to &quot;**1. IBM对Ceph的承诺与投资**&quot;">​</a></h4><ul><li><strong>开源贡献</strong>：IBM（含Red Hat）过去一年向Ceph社区贡献了近80%的代码，是Ceph基金会的钻石成员，并持续赞助Cephlacon等年度活动。</li><li><strong>测试基础设施</strong>：IBM投资200万美元建设上游实验室，用于开发、测试、性能验证及版本发布，目标2025年底迁移至IBM基础设施。</li><li><strong>团队扩展</strong>：IBM开发团队规模翻倍，QE团队参与上游PR测试及稳定版早期验证。</li></ul><h4 id="_2-ceph的核心优势与愿景" tabindex="-1"><strong>2. Ceph的核心优势与愿景</strong> <a class="header-anchor" href="#_2-ceph的核心优势与愿景" aria-label="Permalink to &quot;**2. Ceph的核心优势与愿景**&quot;">​</a></h4><ul><li><strong>技术亮点</strong>：多协议支持（RBD/RGW/CephFS）、弹性扩展（3节点至200节点无差异）、Fast EC性能提升、Bluestore压缩重构、Crimson &amp; Seastar性能优化。</li><li><strong>易用性增强</strong>：Dashboard新增多集群管理、协议操作支持、控制路径强化。</li></ul><h4 id="_3-2026年技术方向" tabindex="-1"><strong>3. 2026年技术方向</strong> <a class="header-anchor" href="#_3-2026年技术方向" aria-label="Permalink to &quot;**3. 2026年技术方向**&quot;">​</a></h4><ul><li><strong>简化运维</strong>：淘汰过时配置，引入Config Profiles和自动调优，全栈QoS能力及MGR模块优化。</li><li><strong>用户驱动开发</strong>：Ceph用户委员会通过调研/论坛收集反馈，指导功能迭代。</li></ul><h4 id="_4-后续行动计划" tabindex="-1"><strong>4. 后续行动计划</strong> <a class="header-anchor" href="#_4-后续行动计划" aria-label="Permalink to &quot;**4. 后续行动计划**&quot;">​</a></h4><ul><li><strong>实验室迁移</strong>：2025年底完成上游资源至IBM基础设施的过渡。</li><li><strong>社区合作</strong>：继续举办SEF Days活动。</li><li><strong>功能落地</strong>：Fast EC性能验证、Crimson/Seastar进展跟踪。</li></ul><p><strong>关键词保留</strong>：Ceph, CRUSH algorithm, OSD, MON, RADOS, Bluestore, RGW, Fast EC, QoS, Tentacle release, Dashboard, Ceph user council, SEF Days</p><p><strong>会议总结</strong>：IBM重申对Ceph的全面投入，聚焦性能优化、易用性提升及社区共建，目标在2026年实现“最佳分布式存储解决方案”。</p>',12)])])}const g=t(r,[["render",s]]);export{m as __pageData,g as default};
